"""Lossless sectioning of the existing editor profile; no LLM or state writes."""
HEADINGS = ['Общие правила', 'Архитектура', 'ПО', 'ИИ', 'Конкурсы', 'Материалы сайта', 'Исследования и знания']
LEGACY_SECTIONS = {'Ценим инструменты и плагины для архитектурного ПО (Rhino, Revit, Blender, Archicad, Vectorworks), которые автоматизируют рутину или дают новый рабочий процесс.': 'ПО', 'Ценим ИИ-инструменты, напрямую применимые в проектировании: генерация 3D, агенты в программах, связка эскиз-модель, ИИ для BIM.': 'ИИ', 'Ценим конкретные здания и проекты с яркой архитектурной идеей, необычным материалом или конструктивным решением, которые можно рассмотреть на фото.': 'Архитектура', 'Ценим конкурсы с практической или студенческой категорией, особенно по ИИ-архитектуре и Blender.': 'Конкурсы', 'Ценим образовательные события (воркшопы, вебинары, хакатоны), где архитектор может освоить новый софт или метод.': 'Исследования и знания', 'Ценим громкие релизы и скандалы вокруг флагманских ИИ-моделей (GPT-6, Opus), влияющие на доступность инструментов.': 'ИИ', 'Ценим исследования о генерации 3D-сцен и объектов из изображений или текста, если они предлагают новый метод, расширяющий проектные возможности архитектора, а не узкотехническое улучшение.': 'ИИ', 'Не ценим рядовые жилые дома, интерьеры квартир и частные виллы без выдающейся архитектурной идеи.': 'Архитектура', 'Не ценим новости о сделках, инвестициях и соглашениях без готового продукта.': 'Общие правила', 'Не ценим ретроспективы, монографии, подборки зданий и редакционные фокусы без концептуальной идеи.': 'Исследования и знания', 'Не ценим туториалы по 3D, не связанные с архитектурой (персонажи, винтажные письма, садовые гномы).': 'ПО', 'Не ценим инструменты, не применимые в архитектурном проектировании (VFX-просмотрщики, риггинг персонажей, генерация игровых миров).': 'ПО', 'Не ценим анонсы строек и проектов на ранней стадии без визуализации готового объекта.': 'Архитектура', 'Не ценим рядовые препринты и узкотехнические статьи по 3D-реконструкции, облакам точек, мешам и Gaussian Splatting без готового архитектурного инструмента или нового проектного метода.': 'ИИ'}

def section_profile(text: str) -> str:
    if any(line.startswith("## ") for line in text.splitlines()):
        return text
    groups = {h: [] for h in HEADINGS}
    for line in text.splitlines():
        if line.strip():
            groups[LEGACY_SECTIONS.get(line.strip(), HEADINGS[0])].append(line)
    return "\n\n".join("## " + h + "\n" + "\n".join(groups[h]) for h in HEADINGS)

CATEGORIES = {"architecture", "software", "ai", "competitions", "site", "knowledge"}
def category_of(item: dict) -> str:
    if item.get("category") in CATEGORIES:
        return item["category"]
    if item.get("competition") or item.get("kind") == "competition":
        return "competitions"
    if item.get("topic") == "neurogeneration":
        return "ai"
    if item.get("kind") == "research":
        return "knowledge"
    if item.get("topic") in ("architecture", "software"):
        return item["topic"]
    return "unclassified"
